def is_palindrome(s):
    t=[c.lower() for c in s if c.isalnum()]
    return t==t[::-1]

def flatten(xs):
    out=[]
    for x in xs:
        out.extend(flatten(x) if isinstance(x,list) else [x])
    return out

def word_count(text):
    d={}
    for w in text.lower().split():
        d[w]=d.get(w,0)+1
    return d

def is_anagram(a,b):
    f=lambda s: sorted(s.replace(' ','').lower())
    return f(a)==f(b)

def fib(n):
    a,b=0,1
    for _ in range(n):
        a,b=b,a+b
    return a

def merge_intervals(iv):
    out=[]
    for s,e in sorted(iv):
        if out and s<=out[-1][1]:
            out[-1][1]=max(out[-1][1],e)
        else:
            out.append([s,e])
    return out

def roman_to_int(s):
    v={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    return sum(-v[c] if i+1<len(s) and v[c]<v[s[i+1]] else v[c] for i,c in enumerate(s))

def dedupe(xs):
    seen=set(); out=[]
    for x in xs:
        if x not in seen:
            seen.add(x); out.append(x)
    return out

import re
def camel_to_snake(s):
    s=re.sub(r'([A-Z]+)([A-Z][a-z])',r'\1_\2',s)
    return re.sub(r'([a-z0-9])([A-Z])',r'\1_\2',s).lower()

def second_largest(nums):
    u=sorted(set(nums))
    return u[-2] if len(u)>1 else None

def rle(s):
    out=[]
    i=0
    while i<len(s):
        j=i
        while j<len(s) and s[j]==s[i]: j+=1
        out.append(f'{s[i]}{j-i}'); i=j
    return ''.join(out)

def balanced(s):
    st=[]; pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{': st.append(c)
        elif c in pairs:
            if not st or st.pop()!=pairs[c]: return False
    return not st

import math
def gcd_all(nums):
    g=0
    for n in nums: g=math.gcd(g,n)
    return g

def caesar(s,k):
    out=[]
    for c in s:
        if c.isascii() and c.isalpha():
            b=ord('a') if c.islower() else ord('A')
            out.append(chr((ord(c)-b+k)%26+b))
        else:
            out.append(c)
    return ''.join(out)

def median(nums):
    s=sorted(nums); n=len(s)
    return s[n//2] if n%2 else (s[n//2-1]+s[n//2])/2
